)
insert into private.exam_prep_assessments(content_version_id,assessment_key,assessment_version,component_code,assessment_type,status,title_en,title_ru,title_uz)
select cv.id,d.k,'av1','P5',d.t,'approved',d.en,d.ru,d.uz from defs d cross join cv on conflict(content_version_id,assessment_key,assessment_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw13_16_probability_v1'), a as (select x.id,x.assessment_key from private.exam_prep_assessments x join cv on cv.id=x.content_version_id), m as (select x.content_key,x.question_id from private.exam_prep_question_content_meta x join cv on cv.id=x.content_version_id), w as (select x.id,x.task_key from private.exam_prep_written_tasks x join cv on cv.id=x.content_version_id), items(akey,ord,ckey,wkey,skill,role,holdout) as (values
('p5_aw13_16_probability_diagnostic',1,'P5PRO05-D01',null,'P5-PRO-05','diagnostic',true),('p5_aw13_16_probability_diagnostic',2,'P5PRO06-D01',null,'P5-PRO-06','diagnostic',true),
('p5_pro05_learning',1,'P5PRO05-L01',null,'P5-PRO-05','learning',false),('p5_pro05_learning',2,'P5PRO05-L02',null,'P5-PRO-05','learning',false),('p5_pro05_learning',3,'P5PRO05-L03',null,'P5-PRO-05','learning',false),('p5_pro05_learning',4,null,'P5PRO05-W01','P5-PRO-05','written',false),
('p5_pro06_learning',1,'P5PRO06-L01',null,'P5-PRO-06','learning',false),('p5_pro06_learning',2,'P5PRO06-L02',null,'P5-PRO-06','learning',false),('p5_pro06_learning',3,'P5PRO06-L03',null,'P5-PRO-06','learning',false),('p5_pro06_learning',4,null,'P5PRO06-W01','P5-PRO-06','written',false),
('p5_pro05_retest',1,'P5PRO05-R01',null,'P5-PRO-05','retest',true),('p5_pro06_retest',1,'P5PRO06-R01',null,'P5-PRO-06','retest',true),
('p5_aw13_16_probability_mixed',1,'P5PRO05-M01',null,'P5-PRO-05','mixed',true),('p5_aw13_16_probability_mixed',2,'P5PRO06-M01',null,'P5-PRO-06','mixed',true)
)
insert into private.exam_prep_assessment_items(assessment_id,item_order,question_id,written_task_id,primary_skill_code,reserve_role,is_holdout)
select a.id,i.ord,m.question_id,w.id,i.skill,i.role,i.holdout from items i join a on a.assessment_key=i.akey left join m on m.content_key=i.ckey left join w on w.task_key=i.wkey on conflict(assessment_id,item_order) do nothing;

do $$ declare v_id bigint; v_skill text; v_bad int; begin
select id into v_id from private.exam_prep_content_versions where content_version='p5_aw13_16_probability_v1' and status='draft'; if v_id is null then raise exception 'P5 AW13 probability draft missing'; end if;
if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id)<>14 then raise exception 'P5 AW13 probability expected 14 questions'; end if;
foreach v_skill in array array['P5-PRO-05','P5-PRO-06'] loop
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='diagnostic')<>1 then raise exception '% diagnostic floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='learning')<>3 then raise exception '% learning floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='retest')<>2 then raise exception '% retest floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='mixed')<>1 then raise exception '% mixed floor',v_skill; end if;
 if (select count(*) from private.exam_prep_written_tasks where content_version_id=v_id and primary_skill_code=v_skill and lifecycle_state='approved')<>1 then raise exception '% written floor',v_skill; end if;
end loop;
select count(*) into v_bad from (select m.id from private.exam_prep_question_content_meta m join public.questions q on q.id=m.question_id left join private.exam_prep_diagnostic_rules r on r.content_meta_id=m.id and r.status='approved' and r.answer_kind='mcq_option' where m.content_version_id=v_id and m.reserve_role='diagnostic' group by m.id,q.correct_answer having count(r.id)<>3 or count(r.id) filter(where r.answer_match=q.correct_answer)<>0) x; if v_bad<>0 then raise exception 'P5 AW13 probability diagnostic failures=%',v_bad; end if;
if (select count(*) from private.exam_prep_question_content_meta m where m.content_version_id=v_id and m.reserve_role='retest' and not exists(select 1 from private.exam_prep_assessment_items i where i.question_id=m.question_id))<>2 then raise exception 'P5 AW13 probability expected 2 isolated R02 holdouts'; end if;
end $$;

update private.exam_prep_question_content_meta m set copyright_status='pass',qa_scope_status='pass',qa_math_status='pass',qa_language_status='pass',qa_technical_status='pass',diagnostic_rule_status=case when reserve_role='diagnostic' then 'approved' else 'not_applicable' end,lifecycle_state='approved',approved_at=now(),updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p5_aw13_16_probability_v1' and cv.status='draft';
update private.exam_prep_content_versions set status='approved',approved_at=now() where content_version='p5_aw13_16_probability_v1' and status='draft';
update private.exam_prep_question_content_meta m set lifecycle_state=case when reserve_role='learning' then 'published' else 'reserve' end,exposure_state=case when reserve_role='learning' then 'released' else 'withheld' end,published_at=case when reserve_role='learning' then now() else null end,updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p5_aw13_16_probability_v1' and cv.status='approved';
update private.exam_prep_written_tasks w set lifecycle_state='published' from private.exam_prep_content_versions cv where cv.id=w.content_version_id and cv.content_version='p5_aw13_16_probability_v1' and cv.status='approved' and w.lifecycle_state='approved';
update private.exam_prep_assessments a set status='published',approved_at=coalesce(a.approved_at,now()) from private.exam_prep_content_versions cv where cv.id=a.content_version_id and cv.content_version='p5_aw13_16_probability_v1' and cv.status='approved' and a.status='approved';
update private.exam_prep_content_versions set status='published',published_at=now() where content_version='p5_aw13_16_probability_v1' and status='approved';

do $$ declare v_program bigint; v_skill text; v_ready int; v_cfg private.exam_prep_feature_config%rowtype; begin
select id into v_program from private.exam_prep_program_versions where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0';
foreach v_skill in array array['P5-PRO-05','P5-PRO-06'] loop if not private.exam_prep_skill_content_ready_v1(v_program,'P5',v_skill) then raise exception 'P5 AW13 probability final not ready=%',v_skill; end if; end loop;
select count(*) into v_ready from private.exam_prep_content_runway_release_skills rs join private.exam_prep_content_runway_releases r on r.id=rs.release_id where r.release_key='aw13_16_core_coverage_iii' and r.component_code='P5' and rs.required_for_release and private.exam_prep_skill_content_ready_v1(v_program,'P5',rs.skill_code); if v_ready<>2 then raise exception 'P5 AW13 probability expected ready=2 got=%',v_ready; end if;
select * into v_cfg from private.exam_prep_feature_config where id=1; if v_cfg.rollout_state<>'off' or v_cfg.core_enabled or v_cfg.ai_enabled or v_cfg.mentor_enabled or not v_cfg.kill_switch then raise exception 'P5 AW13 probability feature escaped fail-closed'; end if;
if exists(select 1 from private.exam_prep_feature_entitlements where entitlement_status='active') then raise exception 'P5 AW13 probability entitlement residue'; end if;
if exists(select 1 from public.questions where book_ref like 'ExamPrep:P5:p5_aw13_16_probability_v1:%' and is_active) then raise exception 'P5 AW13 probability legacy activation'; end if;
end $$;
commit;
